141	        string Id, string Name, string Description,
142	        string CategoryId, string CategoryName,
143	        string SubcategoryId, string SubcategoryName,
144	        IReadOnlyList<ProductAttributeDto> Attributes,
145	        double? AverageRating, int RatingCount,
146	        IReadOnlyList<ProductOfferDto> Offers);
147	
148	    // ProductAttributeDto.cs
149	    public record ProductAttributeDto(string Name, string Value);
150	
151	    // ProductOfferDto.cs
152	    public record ProductOfferDto(string SupplierId, string SupplierName, decimal Price);
153	    ```
154	    **Kein `ViewCount`-Feld in `ProductDetailDto`** — FR-8s Feldliste (Name, Beschreibung, Kategorie, Eigenschaften, Durchschnittsbewertung, Anzahl Bewertungen, Lieferanten+Preis) verlangt keine Anzeige des Zählerstands, nur dessen Erhöhung (FR-9). Absichtlich weggelassen, kein Scope-Creep.
155	  - [x] `ProductsController` bekommt einen zweiten injizierten Service — **Parametername der bestehenden Injection ändert sich** (`service` → `queryService`), da jetzt zwei Services vorliegen:
156	    ```csharp
157	    [ApiController]
158	    [Route("api/products")]
159	    public class ProductsController(ProductQueryService queryService, ProductService detailService) : ControllerBase
160	    {
161	        [HttpGet]
162	        public async Task<IActionResult> GetProducts([FromQuery] int page = 1, [FromQuery] string? categoryId = null, [FromQuery] string? subcategoryId = null, [FromQuery] string? sortBy = null, [FromQuery] string? sortDirection = null, [FromQuery] string? search = null, [FromQuery] string[]? attr = null)
163	        {
164	            var result = await queryService.GetProductsAsync(page, categoryId, subcategoryId, sortBy, sortDirection, search, attr);
165	            return Ok(result);
166	        }
167	
168	        [HttpGet("{id}")]
169	        public async Task<IActionResult> GetProduct(string id)
170	        {
171	            var result = await detailService.GetProductDetailAsync(id);
172	            return result is null ? NotFound() : Ok(result);
173	        }
