229	  - [x] **Route-Parameter reaktiv über `ActivatedRoute.paramMap` abonnieren, nicht per `snapshot` einmalig lesen**: Angulars Default-`RouteReuseStrategy` recycelt die Komponenteninstanz bei einem Navigations-Wechsel *innerhalb derselben Route* (z. B. `/products/P1` → `/products/P2`) und ruft `ngOnInit` dabei **nicht** erneut auf. Über diese Story ist ein solcher direkter Produkt-zu-Produkt-Wechsel zwar nicht erreichbar (einziger Einstieg ist die Produktliste, Task 8), aber `snapshot.paramMap.get('id')` wäre eine stille Falle für jede künftige Story, die z. B. einen „nächstes Produkt"-Link ergänzt. Reaktives Abonnement kostet hier nichts zusätzlich:
230	    ```typescript
231	    import { CurrencyPipe, DecimalPipe } from '@angular/common';
232	    import { Component, OnInit, inject, signal } from '@angular/core';
233	    import { ActivatedRoute } from '@angular/router';
234	
235	    import { Product } from '../../core/models/product.model';
236	    import { ProductService } from '../../core/services/product.service';
237	
238	    @Component({
239	      selector: 'app-product-detail',
240	      imports: [CurrencyPipe, DecimalPipe],
241	      templateUrl: './product-detail.html',
242	      styleUrl: './product-detail.scss'
243	    })
244	    export class ProductDetail implements OnInit {
245	      private readonly route = inject(ActivatedRoute);
246	      private readonly productService = inject(ProductService);
247	
248	      readonly product = signal<Product | null>(null);
249	      readonly notFound = signal(false);
250	      readonly error = signal(false);
251	
252	      ngOnInit(): void {
253	        this.route.paramMap.subscribe((params) => this.load(params.get('id')!));
254	      }
255	
256	      private load(id: string): void {
257	        this.product.set(null);
258	        this.notFound.set(false);
259	        this.error.set(false);
260	        this.productService.getProduct(id).subscribe({
261	          next: (product) => this.product.set(product),
262	          error: (err) => {
263	            if (err?.status === 404) {
264	              this.notFound.set(true);
265	            } else {
266	              this.error.set(true);
267	            }
268	          }
269	        });
270	      }
271	    }
272	    ```
